def int_to_bytes(value, length):
    """Convert integer to bytes with specified length (big-endian)"""
    return value.to_bytes(length, byteorder='big')

def xor_bytes(a, b):
    """XOR two byte strings"""
    return bytes(x ^ y for x, y in zip(a, b))

def hexdump(data):
    """Print hexdump of bytes"""
    return ' '.join(f'{b:02x}' for b in data)

def find_cube_root(n):
    """Find the cube root of n using binary search"""
    left = 0
    right = n

    while left <= right:
        mid = (left + right) // 2
        cube = mid ** 3

        if cube == n:
            return mid
        elif cube < n:
            left = mid + 1
        else:
            right = mid - 1

    return right  # Return closest value

