    """Convert bytes to integer (big-endian)"""
    return int.from_bytes(data, byteorder='big')

def int_to_bytes(value, length):
    """Convert integer to bytes with specified length (big-endian)"""
    try:
        return int(value).to_bytes(length, byteorder='big')
    except OverflowError:
        # If we overflow, try padding with zeros
        result = int(value).to_bytes((value.bit_length() + 7) // 8, byteorder='big')
        return b'\x00' * (length - len(result)) + result

def xor_bytes(a, b):
    """XOR two byte strings"""
    return bytes(x ^ y for x, y in zip(a, b))

def hexdump(data):
    """Print hexdump of bytes"""
    return ' '.join(f'{b:02x}' for b in data)

