print(f"Y_os length: {len(y_os)} bytes")
print(f"Encrypted file length: {len(enc_file)} bytes")
print(f"First 32 bytes of Y_os: {hexdump(y_os[:32])}")
print(f"First 32 bytes of enc_file: {hexdump(enc_file[:32])}")

